import flax.linen as nn
import jax.numpy as jnp
from jax import random
from ray import tune
import optax
import jax

def _define_hyperparameters():
    return {
        'learning_rate': tune.choice([4e-4]),
        'entropy_coef': tune.choice([0.01]),
        'value_loss_coef': tune.choice([0.5]),
        'cnn_features_1': tune.choice([32]),
        'cnn_features_2': tune.choice([64]),
        'gru_features': tune.choice([256])
    }

class MinimalSokobanNet(nn.Module):
    hparams: dict

    @nn.compact
    def __call__(self, x, rnn_state, debug=False):
        # Initial Convolutional layers for feature extraction
        x = nn.Conv(features=self.hparams.get('cnn_features_1', 32), kernel_size=(3, 3), strides=(1, 1))(x)
        x = nn.relu(x)
        x = nn.Conv(features=self.hparams.get('cnn_features_2', 64), kernel_size=(3, 3), strides=(1, 1))(x)
        x = nn.relu(x)

        # Flatten features for GRU
        x = x.reshape((x.shape[0], -1))

        # GRU for temporal reasoning
        new_rnn_state, x = nn.GRUCell(features=self.hparams.get('gru_features', 256))(rnn_state, x)

        # Policy and Value heads
        logits = nn.Dense(features=4)(x) # 4 actions
        value = nn.Dense(features=1)(x)

        return (logits, value, new_rnn_state)

def create_network(hparams):
    return MinimalSokobanNet(hparams)

def create_optimizer(learning_rate: float = 4e-4):
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adamw(learning_rate=learning_rate, weight_decay=1e-4)
    )

